/**
 * Public Course Lab publications. Authored bundles live in independent JSON
 * files, generated by the authenticated GitHub staff publisher.
 * Importing this module NEVER fetches or advertises non-published lessons.
 */
import {validateLearnBundle} from './ns-learn-engine-v2.mjs';
import {loadStrategyAtlas,buildStrategyBundle} from './ns-strategy-curriculum.mjs?v=psy-atlas-20261120';
export const PUBLISHED_COURSE_BUNDLES=Object.freeze({});
const bundles=new Map();
let index={version:1,courses:{}},indexLoaded=false,inflight=null;
const base=new URL('./learn-content/',import.meta.url);
const validId=id=>/^[a-z0-9][a-z0-9-]{0,119}$/.test(String(id||''));
export const getLearnIndex=()=>index;
export const getLearnContent=id=>bundles.get(id)||PUBLISHED_COURSE_BUNDLES[id]||null;
export const hasPublishedLearnCourse=id=>!!index.courses[id]||!!PUBLISHED_COURSE_BUNDLES[id];
export async function loadPublishedLearnIndex({refresh=false}={}){
 if(indexLoaded&&!refresh)return index;
 if(inflight)return inflight;
 if(typeof fetch!=='function')return index;
 inflight=(async()=>{
  const response=await fetch(new URL('index.json',base),{cache:'no-store'});
  if(!response.ok)throw Error('Course availability could not be loaded ('+response.status+').');
  const data=await response.json();
  if(data?.version!==1||!data.courses||typeof data.courses!=='object'||Array.isArray(data.courses))throw Error('Invalid published course index.');
  const allowed={};
  for(const [id,record] of Object.entries(data.courses)){
   if(validId(id)&&record?.status!=='unpublished'&&Number.isInteger(record?.version)&&record.version>=1)allowed[id]={version:record.version,title:typeof record.title==='string'?record.title.slice(0,160):'',description:typeof record.description==='string'?record.description.slice(0,400):''};
  }
  index={version:1,courses:allowed};indexLoaded=true;
  for(const [id,bundle] of bundles)if(bundle.version!==allowed[id]?.version)bundles.delete(id);
  return index;
 })().finally(()=>{inflight=null;});
 return inflight;
}
export async function loadPublishedLearnBundle(id){
 if(!validId(id))return null;
 await loadPublishedLearnIndex();
 const record=index.courses[id];
 if(!record)return PUBLISHED_COURSE_BUNDLES[id]||null;
 const cached=bundles.get(id);
 if(cached?.version===record.version)return cached;
 const url=new URL('courses/'+id+'.json',base);
 url.searchParams.set('v',String(record.version));
 const response=await fetch(url,{cache:'no-store'});
 if(!response.ok)throw Error('Published course could not be downloaded ('+response.status+').');
 const bundle=await response.json();
 const errors=validateLearnBundle(bundle,id);
 if(errors.length||bundle.version!==record.version)throw Error('Published course failed validation: '+errors.slice(0,3).join('; '));
 const atlasSource=await loadStrategyAtlas();
 const strategyBundle=buildStrategyBundle(bundle,atlasSource);
 if(id==='self-esteem'){
  const authoredResponse=await fetch(new URL('contingent-self-worth-unit.json?v=20261121-authored-1',base),{cache:'no-store'});
  if(!authoredResponse.ok)throw Error('The contingent self-worth unit could not be downloaded ('+authoredResponse.status+').');
  const authored=await authoredResponse.json();
  if(authored?.id!=='contingent-self-worth'||authored?.screenCount!==80||authored.lessons?.length!==8||authored.reviews?.length!==3||authored.intro?.screens?.length!==2)throw Error('Incomplete contingent self-worth unit publication.');
  const isGraded=s=>s.paragraphs?.some(p=>/^(?:Correct answer|Best answer|Best-supported answer|Best-supported response):\s*[A-D]/i.test(p))||s.id==='2.3';
  const toLesson=(entry,reviewDelayDays=0)=>({
   id:entry.id,title:entry.title,version:1,number:entry.number||'',authoringType:'contingent-self-worth',
   editorialStatus:'authored',screens:entry.screens,checkCount:entry.screens.filter(isGraded).length,
   reviewDelayDays,objective:entry.teachingPurpose||'Practise recognising and responding to contingent self-worth.'
  });
  const opening=toLesson({...authored.intro,title:'Welcome · When worth depends on outcomes'});
  const teaching=authored.lessons.map(entry=>toLesson(entry));
  const reviews=authored.reviews.map((entry,i)=>toLesson(entry,[1,7,21][i]));
  strategyBundle.modules=[
   {id:'self-esteem-authored-contingent-worth',kind:'authored',title:authored.title,lessons:[opening,...teaching]},
   {id:'self-esteem-contingent-worth-reviews',kind:'review',title:'Return to what you have learnt',lessons:reviews},
   ...strategyBundle.modules
  ];
  strategyBundle.authoredUnitCount=8;
 }
 bundles.set(id,strategyBundle);
 return strategyBundle;
}
